/* DWARF original prototype: bool IsAffectFlag(CHARACTER * this, DWORD dwAff) */

bool __thiscall CHARACTER::IsAffectFlag(CHARACTER *this,DWORD dwAff)

{
  return (bool)((byte)((this->m_afAffectFlag).bits[(int)(dwAff - 1) >> 5] >>
                      ((byte)(dwAff - 1) & 0x1f)) & 1);
}

void SendAffectRemovePacket(LPDESC d,DWORD pid,DWORD type,BYTE point)

{
  TPacketGDRemoveAffect ptod;
  TPacketGCAffectRemove ptoc;
  
  ptoc.bApplyOn = point;
  ptoc.dwType = type;
  ptoc.bHeader = '\x7f';
  DESC::Packet(d,&ptoc,6);
  ptod.dwType = type;
  ptod.dwPID = pid;
  ptod.bApplyOn = point;
  CLIENT_DESC::DBPacket(db_clientdesc,'!',0,&ptod,9);
  return;
}

/* DWARF original prototype: void CreateFly(CHARACTER * this, BYTE bType, LPCHARACTER pkVictim) */

void __thiscall CHARACTER::CreateFly(CHARACTER *this,BYTE bType,LPCHARACTER pkVictim)

{
  TPacketGCCreateFly packFly;
  
  packFly.bHeader = 'F';
  packFly.bType = bType;
  packFly.dwStartVID = (this->m_vid).m_id;
  packFly.dwEndVID = (pkVictim->m_vid).m_id;
  CEntity::PacketAround(&this->super_CEntity,&packFly,10,(LPENTITY)0x0);
  return;
}
